package main
import("encoding/json";"fmt";"os";gp "github.com/CaliLuke/go-guitar-pro")
type Result struct {Case string;Diagnostics []gp.ScoreDiagnostic;Report gp.ExportReport;Error string;OutputBytes int;RoundError string;Masks []int;Tunings []int;Unmutated bool}
func main(){var out []Result;for _,name:=range []string{"legacy-invalid-six-mask","legacy-valid-four-mask","staff-direct-four-mask","second-staff-six-mask","legacy-whole-capo-bounds"}{
 s,e:=gp.ParseFile("testdata/gp8/partial-capo-asymmetric.gp");if e!=nil{panic(e)};tr:=&s.Tracks[0];tr.Strings=tr.Strings[:4];tr.Measures[0].Voices[0].Beats=tr.Measures[0].Voices[0].Beats[:4];for i:=range tr.Measures[0].Voices[0].Beats{tr.Measures[0].Voices[0].Beats[i].Notes[0].AccidentalMode=gp.NoteAccidentalDefault}
 if name!="legacy-invalid-six-mask"{tr.Staves[0].PartialCapo.Strings=[]bool{true,false,false,true}}
 if name=="staff-direct-four-mask"{tr.Staves[0].Strings=tr.Strings;tr.Strings=nil}
 if name=="second-staff-six-mask"{second:=tr.Staves[0];second.Measures=append([]gp.Measure(nil),second.Measures...);for i:=range second.Measures{second.Measures[i].StaffIndex=1};second.PartialCapo=&gp.PartialCapo{Offset:3,Strings:[]bool{true,false,false,true,false,false}};tr.Staves=append(tr.Staves,second)}
 if name=="legacy-whole-capo-bounds"{tr.CapoFret=100}
 before,_:=json.Marshal(s);r:=Result{Case:name};r.Diagnostics=gp.ValidateSong(s);data,report,e:=gp.ExportWithReport(s,gp.ExportFormatGP8,gp.ExportOptions{});r.Report=report;r.OutputBytes=len(data);if e!=nil{r.Error=e.Error()}else{round,re:=gp.Parse(data);if re!=nil{r.RoundError=re.Error()}else{for _,st:=range round.Tracks[0].Staves{r.Tunings=append(r.Tunings,len(st.Strings));r.Masks=append(r.Masks,len(st.PartialCapo.Strings))}}};after,_:=json.Marshal(s);r.Unmutated=string(before)==string(after);out=append(out,r)
 };b,e:=json.MarshalIndent(out,"","  ");if e!=nil{panic(e)};fmt.Fprintln(os.Stdout,string(b))}
